#!/usr/bin/env bash
# Regenerates the golden env files from main's deploy-server.sh (the version
# before the on-prem installer changed it), so the engine tests prove that the
# existing TLS modes still render the same backend/.env and root .env.
#
#   installer/internal/engine/testdata/golden/generate-from-main.sh [REF]
#
# REF defaults to 70e17044 (main when the on-prem installer branched). Run it
# from anywhere inside the repo. Docker is replaced by ../stubs/docker, so
# nothing is installed or started.
set -euo pipefail

REF="${1:-70e17044}"
HERE="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
TESTDATA="$(dirname "$HERE")"
REPO="$(git -C "$HERE" rev-parse --show-toplevel)"
WORK="$(mktemp -d)"
trap 'rm -rf "$WORK"' EXIT

for mode in acme-http acme-dns internal byo; do
  dir="${WORK}/${mode}"
  mkdir -p "${dir}/scripts" "${dir}/backend"
  git -C "$REPO" show "${REF}:scripts/deploy-server.sh" > "${dir}/scripts/deploy-server.sh"
  git -C "$REPO" archive "$REF" deploy/caddy docker-compose.server.yml | tar -x -C "$dir"
  if [ "$mode" = byo ]; then
    mkdir -p "${dir}/deploy/caddy/certs"
    echo "placeholder" > "${dir}/deploy/caddy/certs/cert.pem"
    echo "placeholder" > "${dir}/deploy/caddy/certs/key.pem"
  fi
  cat "${TESTDATA}/configs/${mode}.env" "${TESTDATA}/configs/common.env" > "${dir}/cfg.env"
  env -i PATH="${TESTDATA}/stubs:/usr/bin:/bin" HOME="$dir" \
    bash "${dir}/scripts/deploy-server.sh" "${dir}/cfg.env" > "${dir}/out.log" 2>&1 \
    || { cat "${dir}/out.log"; exit 1; }
  grep -v '^# Generated by deploy-server.sh' "${dir}/backend/.env" > "${HERE}/${mode}.backend.env"
  grep -v '^# Generated by deploy-server.sh' "${dir}/.env" > "${HERE}/${mode}.root.env"
  echo "wrote ${mode}.backend.env and ${mode}.root.env"
done
